export const storeCouchSample = mutation({
  args: {
    sampleId: v.string(),
    routes: v.array(
      v.object({
        routeId: v.string(),
        provenance: v.union(
          v.literal('scraped_promoted'),
          v.literal('ai_reconstructed'),
          v.literal('name_routed'),
